		CHIAKI_LOGE(decoder->log, "OMX_SetParameter failed for display params");
}

CHIAKI_EXPORT bool chiaki_pi_decoder_video_sample_cb(uint8_t *buf, size_t buf_size, void *user)
{
	return push_buffer(user, buf, buf_size);
}

